        out_msg->name.data = (char *)malloc(name_len + 1);
        if (!out_msg->name.data) {
            recursive_nested_msg_t_free(out_msg);
            return (-1);
        }

        memcpy(out_msg->name.data, in_buf + dyn_off, name_len);
        out_msg->name.data[name_len] = '\0';
        dyn_off += name_len;
